USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), (DATE_PART('EPOCH_MILLISECOND', SYSDATE()) - DATE_PART('EPOCH_MILLISECOND', :STEPSTARTTIME)), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.originalContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.proposedContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), (DATE_PART('EPOCH_MILLISECOND', SYSDATE()) - DATE_PART('EPOCH_MILLISECOND', :STEPSTARTTIME)), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.finalContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), (DATE_PART('EPOCH_MILLISECOND', SYSDATE()) - DATE_PART('EPOCH_MILLISECOND', :STEPSTARTTIME)), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.originalContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.proposedContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), (DATE_PART('EPOCH_MILLISECOND', SYSDATE()) - DATE_PART('EPOCH_MILLISECOND', :STEPSTARTTIME)), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.finalContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), (DATE_PART('EPOCH_MILLISECOND', SYSDATE()) - DATE_PART('EPOCH_MILLISECOND', :STEPSTARTTIME)), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.originalContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                END;
                        END;
                        END IF;
                        OVERALLSTATUS := 'COMPLETED';
                    EXCEPTION
                        WHEN OTHER THEN
                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
                            -- Validation errors
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'COMPLETED'), 'FailedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'FAILED'), 'WarningSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
                                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                            Status = 'WARNING'), 'TotalProcessingMs',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(DurationMs) FROM
                                            T_StepResults
                                               ), 'TotalRowsProcessed',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            SUM(RowsAffected) FROM
                                            T_StepResults
                                               ), 'ConsolidatedBudgetID', :CONSOLIDATIONBUDGETID, 'UnreconciledItems', :UNRECONCILEDCOUNT, 'TotalVariance', :VARIANCETOTAL), 'Metrics')
                            )), 'FinancialCloseResults')
                           );
    -- Cleanup
                                            DROP TABLE IF EXISTS T_CostCenterSnapshot;
                                            DROP TABLE IF EXISTS T_STEPRESULTS;
                                            DROP TABLE IF EXISTS T_VALIDATIONERRORS;
                                            SC_EXIT_CODE := CASE
                        :OVERALLSTATUS
                        WHEN 'COMPLETED' THEN 0 WHEN 'VALIDATION_FAILED' THEN 1 ELSE -1 END;
                END;
        BEGIN
            CALL SC_PROCESS();
            RETURN :SC_EXIT_CODE;
        END;
    $$;

messages.proposedContent:
USE DATABASE <%financial_planning%>;

/*
    usp_PerformFinancialClose - Comprehensive period-end close orchestration procedure

    Dependencies:
        - Tables: All tables in the Planning schema
        - Views: All views in the Planning schema  
        - Functions: All functions in the Planning schema
        - Procedures: usp_ProcessBudgetConsolidation, usp_ExecuteCostAllocation, 
                      usp_ReconcileIntercompanyBalances
        - Types: BudgetLineItemTableType, AllocationResultTableType

    ============================================================================
    SNOWFLAKE MIGRATION CHALLENGES:
    ============================================================================
    1. Service Broker messaging (commented but shows pattern)
    2. EXEC nested procedures with OUTPUT params
    3. Transaction nesting with @@TRANCOUNT checks
    4. Multiple RETURN points with different codes
    5. DISABLE/ENABLE TRIGGER for maintenance
    6. CHECKPOINT and DBCC SHRINKDATABASE (admin operations)
    7. sp_OA* automation procedures
    8. Send email via sp_send_dbmail
    9. Agent job scheduling via msdb procedures
    10. Change Data Capture (CDC) queries
    11. Extended events session management
    12. Query Store operations
    13. Memory-optimized tables with NATIVE_COMPILATION
    14. Temporal table FOR SYSTEM_TIME queries
    ============================================================================
*/
CREATE OR REPLACE PROCEDURE Planning.usp_PerformFinancialClose
    --** SSC-FDM-0041 - DEFAULT PARAMETERS WERE REORDERED TO THE END OF THE PARAMETER LIST TO MATCH SNOWFLAKE REQUIREMENTS. CALLERS USING POSITIONAL ARGUMENTS MAY NEED TO BE UPDATED **
    (
    -- SOFT, HARD, FINAL
    -- Semicolon-separated emails
    FISCALPERIODID INT, CLOSINGUSERID INT, CLOSERESULTS OUT VARIANT, OVERALLSTATUS OUT STRING, CLOSETYPE STRING DEFAULT 'SOFT', RUNCONSOLIDATION BOOLEAN DEFAULT 1, RUNALLOCATIONS BOOLEAN DEFAULT 1, RUNRECONCILIATION BOOLEAN DEFAULT 1, SENDNOTIFICATIONS BOOLEAN DEFAULT 1, NOTIFICATIONRECIPIENTS STRING DEFAULT NULL, FORCECLOSE BOOLEAN DEFAULT 0)
    RETURNS VARCHAR
    LANGUAGE SQL
    COMMENT = '{ "origin": "sf_sc", "name": "snowconvert", "version": {  "major": 2,  "minor": 54,  "patch": "2-Pr" }, "attributes": {  "component": "transact",  "convertedOn": "11/21/2026",  "domain": "no-domain-provided",  "migrationid": "wACiAZC/6HqmQFXn1qdfyw==" }}'
    EXECUTE AS CALLER
    AS
    $$
        DECLARE
            SC_EXIT_CODE VARCHAR;

            -- =========================================================================
            -- Declarations and initialization
            -- =========================================================================
            PROCSTARTTIME TIMESTAMP_NTZ(7);
            STEPSTARTTIME TIMESTAMP_NTZ(7);
            CURRENTSTEP NVARCHAR(100);
            CLOSERUNID VARCHAR;
            ERRORMESSAGE NVARCHAR(4000);
            RETURNCODE INT := 0;
            FISCALYEAR SMALLINT;
            FISCALMONTH TINYINT;
            PERIODNAME NVARCHAR(50);
            ISALREADYCLOSED BOOLEAN;

            -- Nested procedure output variables
            CONSOLIDATIONBUDGETID INT;
            CONSOLIDATIONROWS INT;
            CONSOLIDATIONERROR NVARCHAR(4000);
            ALLOCATIONROWS INT;
            ALLOCATIONWARNINGS NVARCHAR;
            RECONCILIATIONXML VARIANT;
            UNRECONCILEDCOUNT INT;
            VARIANCETOTAL DECIMAL(19, 4);
            ACTIVEBUDGETID INT;

            -- Check for pending journals
            PENDINGJOURNALS INT;

            -- Query cost center history using FOR SYSTEM_TIME
            -- This temporal query syntax doesn't exist in Snowflake
            SNAPSHOTTIME TIMESTAMP_NTZ(7);

            -- Create empty TVP for allocation results
            /* Manual resolution: Planning.AllocationResultTableType is a table-valued
               parameter type, which Snowflake has no equivalent for. The converted
               usp_ExecuteCostAllocation takes ALLOCATIONRESULTS as an ARRAY, and this
               variable only ever passes an empty TVP, so an empty ARRAY is exact. */
            EMPTYALLOCRESULTS ARRAY := ARRAY_CONSTRUCT();
            EFFECTIVEBUDGETID INT;
            RECONCILEBUDGETID INT;
            AUTOCREATEADJ BOOLEAN;
            EMAILBODY NVARCHAR;
            EMAILSUBJECT NVARCHAR(255);
            SC_PROCESS PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
--                    --** SSC-FDM-TS0029 - SET NOCOUNT STATEMENT IS COMMENTED OUT, WHICH IS NOT APPLICABLE IN SNOWFLAKE. **
--                    SET NOCOUNT ON;
                    -- Manual resolution: SET XACT_ABORT OFF removed; no Snowflake
                    -- equivalent. Errors are handled per step for orchestration.

                    PROCSTARTTIME := SYSDATE();


                    CLOSERUNID := UUID_STRING();







                    -- Step tracking
                    CREATE OR REPLACE TEMPORARY TABLE T_STEPRESULTS (
                        StepNumber INT IDENTITY(1,1) ORDER PRIMARY KEY,
                        StepName NVARCHAR(100),
                        StartTime TIMESTAMP_NTZ(7),
                        EndTime TIMESTAMP_NTZ(7),
                        DurationMs INT,
                        Status VARCHAR(20),
                        RowsAffected INT,
                        ErrorMessage NVARCHAR(4000),
                        OutputData VARIANT
                    );










                    -- Validation result table
                    CREATE OR REPLACE TEMPORARY TABLE T_VALIDATIONERRORS (
                        ErrorCode VARCHAR(20),
                        ErrorMessage NVARCHAR(500),
                        Severity VARCHAR(10),  -- ERROR, WARNING

                        BlocksClose BOOLEAN
                    );

                    -- Check for pending journals

                    -- Query cost center history using FOR SYSTEM_TIME
                    -- This temporal query syntax doesn't exist in Snowflake
                    BEGIN
                        -- =====================================================================
                        -- Step 1: Validate period and prerequisites
                        -- =====================================================================
                        CURRENTSTEP := 'Period Validation';
                        STEPSTARTTIME := SYSDATE();
                        LET FISCALYEAR_RESULTSET_1 RESULTSET :=
                        (
                            SELECT
                                FiscalYear AS FISCALYEAR_VALUE,
                                FiscalMonth AS FISCALMONTH_VALUE,
                                PeriodName AS PERIODNAME_VALUE,
                                IsClosed AS ISALREADYCLOSED_VALUE
                            FROM
                                <%financial_planning%>.Planning.FiscalPeriod
                            WHERE
                                FiscalPeriodID = :FISCALPERIODID
                        );
                        FOR FISCALYEAR_ROW_1 IN FISCALYEAR_RESULTSET_1 DO
                            FISCALYEAR := FISCALYEAR_ROW_1.FISCALYEAR_VALUE;
                            FISCALMONTH := FISCALYEAR_ROW_1.FISCALMONTH_VALUE;
                            PERIODNAME := FISCALYEAR_ROW_1.PERIODNAME_VALUE;
                            ISALREADYCLOSED := FISCALYEAR_ROW_1.ISALREADYCLOSED_VALUE;
                        END FOR;
                        IF (:FISCALYEAR IS NULL) THEN
                            BEGIN
                                ERRORMESSAGE := 'Fiscal period not found: ' || CAST(:FISCALPERIODID AS VARCHAR);
                                INSERT INTO T_VALIDATIONERRORS VALUES ('INVALID_PERIOD', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        IF (:ISALREADYCLOSED = 1 AND :FORCECLOSE = 0) THEN
                            BEGIN
                                ERRORMESSAGE := 'Period is already closed. Use @ForceClose=1 to reprocess.';
                                INSERT INTO T_VALIDATIONERRORS VALUES ('ALREADY_CLOSED', :ERRORMESSAGE, 'ERROR', 1);
                            END;
                        END IF;
                        -- Check prior periods are closed (for HARD and FINAL close)
                        IF (:CLOSETYPE IN ('HARD', 'FINAL')) THEN
                        BEGIN
                                IF (EXISTS (
                                                   SELECT 1 FROM
                                                       <%financial_planning%>.Planning.FiscalPeriod
                                                   WHERE
                                                       FiscalYear = :FISCALYEAR
                                                     AND FiscalMonth < :FISCALMONTH
                                                     AND IsClosed = 0
                                                     AND IsAdjustmentPeriod = 0
                                               )) THEN
                                               BEGIN
                                                       ERRORMESSAGE := 'Prior periods must be closed before ' || :CLOSETYPE || ' close';
                                                   INSERT INTO T_VALIDATIONERRORS VALUES ('PRIOR_OPEN', :ERRORMESSAGE, 'ERROR', 1);
                                               END;
                                END IF;
                        END;
                        END IF;

                    SELECT
                            COUNT(*)
                        INTO
                            :PENDINGJOURNALS
                    FROM
                            <%financial_planning%>.Planning.ConsolidationJournal cj
                    INNER JOIN
                                <%financial_planning%>.Planning.FiscalPeriod fp
                                ON cj.FiscalPeriodID = fp.FiscalPeriodID
                    WHERE
                            fp.FiscalPeriodID = :FISCALPERIODID
                      AND
                            --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                            cj.StatusCode IN ('DRAFT', 'SUBMITTED');
                        IF (:PENDINGJOURNALS > 0) THEN
                            BEGIN
                                ERRORMESSAGE := CONCAT(COALESCE(:PENDINGJOURNALS :: STRING, ''), ' pending journal(s) must be posted or rejected');
                                INSERT INTO T_VALIDATIONERRORS VALUES ('PENDING_JOURNALS', :ERRORMESSAGE,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 'ERROR' ELSE 'WARNING' END,
                                    CASE WHEN :CLOSETYPE = 'FINAL' THEN 1 ELSE 0 END);
                            END;
                        END IF;

                    -- Log validation step
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                        SELECT
                            :CURRENTSTEP,
                            :STEPSTARTTIME,
                            SYSDATE(),
                            DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                            CASE WHEN EXISTS (SELECT 1 FROM
                                                       T_ValidationErrors
                                               WHERE
                                                       BlocksClose = 1) THEN 'FAILED' ELSE 'COMPLETED' END,
                            (SELECT
                                               COUNT(*) FROM
                                               T_ValidationErrors
                            )
                        ;
                        -- Stop if blocking errors
                        IF (EXISTS (SELECT 1 FROM
                                T_ValidationErrors
                            WHERE
                                BlocksClose = 1)) THEN
                        BEGIN
                                OVERALLSTATUS := 'VALIDATION_FAILED';
                                BEGIN
                                               CALL BuildResults();
                                               RETURN 'PROCESS FINISHED';
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 2: Create snapshot point (using temporal table)
                        -- =====================================================================
                        CURRENTSTEP := 'Create Snapshot';
                        STEPSTARTTIME := SYSDATE();
                        SNAPSHOTTIME := SYSDATE();
                        CREATE OR REPLACE TEMPORARY TABLE T_CostCenterSnapshot AS
                            SELECT
                                cc.CostCenterID,
                                cc.CostCenterCode,
                                cc.CostCenterName,
                                cc.ParentCostCenterID,
                                cc.AllocationWeight,
                        'CURRENT' AS SnapshotType
                    FROM
                                <%financial_planning%>.Planning.CostCenter
--                    BEHAVIOURAL DIFFERENCE (was SSC-EWI-0021, FOR SYSTEM_TIME):
--                    the source read the temporal history of Planning.CostCenter as of
--                    @SnapshotTime. Snowflake has no FOR SYSTEM_TIME clause, so this
--                    now reads the CURRENT rows: a close re-run for a past period will
--                    snapshot today's cost centres, not those in effect at the time.
--                    To restore point-in-time behaviour, read Planning.CostCenterHistory
--                    (or use Time Travel, which is limited to the retention window).
--                    FOR SYSTEM_TIME AS OF @SnapshotTime
                                                        cc -- Temporal query
                    WHERE
                                cc.IsActive = 1;
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                    VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', (
                            SELECT
                                COUNT(*)
                            FROM
                                T_CostCenterSnapshot
                        ));
                        -- =====================================================================
                        -- Step 3: Run Consolidation (nested procedure call)
                        -- =====================================================================
                        IF (:RUNCONSOLIDATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Budget Consolidation';
                                STEPSTARTTIME := SYSDATE();
                                LET ACTIVEBUDGETID_RESULTSET_2 RESULTSET :=
                                (

                                               -- Find active budget for this period
                                               SELECT TOP 1
                                                       BudgetHeaderID AS ACTIVEBUDGETID_VALUE
                                               FROM
                                                       <%financial_planning%>.Planning.BudgetHeader bh
                                               INNER JOIN
                                            <%financial_planning%>.Planning.FiscalPeriod fp
                                            ON fp.FiscalPeriodID BETWEEN bh.StartPeriodID AND bh.EndPeriodID
                                               WHERE
                                                       fp.FiscalPeriodID = :FISCALPERIODID
                                                 AND
                                                       --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                                       bh.StatusCode IN ('APPROVED', 'LOCKED')
                                               ORDER BY bh.VersionNumber DESC NULLS LAST
                                );
                                FOR ACTIVEBUDGETID_ROW_2 IN ACTIVEBUDGETID_RESULTSET_2 DO
                                               ACTIVEBUDGETID := ACTIVEBUDGETID_ROW_2.ACTIVEBUDGETID_VALUE;
                                END FOR;
                                IF (:ACTIVEBUDGETID IS NOT NULL) THEN
                                               BEGIN
                                                       BEGIN
                                            -- Nested procedure execution with OUTPUT parameters
                                            CALL <%financial_planning%>.Planning.usp_ProcessBudgetConsolidation(SOURCEBUDGETHEADERID => :ACTIVEBUDGETID, TARGETBUDGETHEADERID => :CONSOLIDATIONBUDGETID, CONSOLIDATIONTYPE => 'FULL', INCLUDEELIMINATIONS => 1, RECALCULATEALLOCATIONS => 0, USERID => :CLOSINGUSERID, ROWSPROCESSED => :CONSOLIDATIONROWS, ERRORMESSAGE => :CONSOLIDATIONERROR);

                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
                                                       EXCEPTION
                                            WHEN OTHER THEN
                                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                        'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                IF (:CLOSETYPE = 'FINAL') THEN
                                                    RAISE;
                                                END IF;
                                                       END;
                                               END;
                                ELSE
                                               BEGIN
                                                   INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                   VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                           'SKIPPED', 'No active budget found for period');
                                               END;
                                END IF;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 4: Run Cost Allocations
                        -- =====================================================================
                        IF (:RUNALLOCATIONS = 1) THEN

                            -- Create empty TVP for allocation results
                        BEGIN
                                CURRENTSTEP := 'Cost Allocations';
                                STEPSTARTTIME := SYSDATE();

                                EFFECTIVEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ExecuteCostAllocation(BUDGETHEADERID => :EFFECTIVEBUDGETID, ALLOCATIONRULEIDS => NULL, FISCALPERIODID => :FISCALPERIODID, DRYRUN => 0, CONCURRENCYMODE => 'EXCLUSIVE', ALLOCATIONRESULTS =>
                                               :EMPTYALLOCRESULTS, ROWSALLOCATED => :ALLOCATIONROWS, WARNINGMESSAGES => :ALLOCATIONWARNINGS);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :ALLOCATIONROWS, :ALLOCATIONWARNINGS);
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 5: Run Intercompany Reconciliation
                        -- =====================================================================
                        IF (:RUNRECONCILIATION = 1) THEN
                        BEGIN
                                CURRENTSTEP := 'Intercompany Reconciliation';
                                STEPSTARTTIME := SYSDATE();
                                RECONCILEBUDGETID := NVL(:CONSOLIDATIONBUDGETID, :ACTIVEBUDGETID);
                                AUTOCREATEADJ := CASE WHEN :CLOSETYPE = 'FINAL' THEN 0 ELSE 1 END;
                                BEGIN
                                               CALL <%financial_planning%>.Planning.usp_ReconcileIntercompanyBalances(BUDGETHEADERID => :RECONCILEBUDGETID, RECONCILIATIONDATE => NULL, ENTITYCODES => NULL, TOLERANCEAMOUNT => 0.01, AUTOCREATEADJUSTMENTS => :AUTOCREATEADJ, RECONCILIATIONREPORTXML => :RECONCILIATIONXML, UNRECONCILEDCOUNT => :UNRECONCILEDCOUNT, TOTALVARIANCEAMOUNT => :VARIANCETOTAL);

                                INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage, OutputData)
                                VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                        CASE
                                            WHEN :UNRECONCILEDCOUNT = 0 THEN 'COMPLETED'
                                            WHEN :CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0 THEN 'FAILED'
                                            ELSE 'WARNING'
                                        END, :UNRECONCILEDCOUNT,
                                        CASE WHEN :UNRECONCILEDCOUNT > 0
                                             THEN CONCAT(COALESCE(:UNRECONCILEDCOUNT :: STRING, ''), ' unreconciled items, variance: ', COALESCE(CASE
                                                WHEN (:VARIANCETOTAL) IS NULL
                                                    THEN null
                                                WHEN (:VARIANCETOTAL) < 0
                                                    THEN '($' || TO_CHAR(-1 * (:VARIANCETOTAL), 'FM999,999,999,999,990.00') || ')'
                                                ELSE '$' || TO_CHAR(:VARIANCETOTAL, 'FM999,999,999,999,990.00')
                                            END /*** SSC-FDM-0036 - TRANSFORMATION OF 'C' FORMAT MAY HAVE A DIFFERENT BEHAVIOR IN SNOWFLAKE. ***/ :: STRING, ''))
                                             ELSE NULL END, :RECONCILIATIONXML);
                                               -- Block FINAL close if unreconciled
                                               IF (:CLOSETYPE = 'FINAL' AND :UNRECONCILEDCOUNT > 0) THEN
                                               BEGIN
                                            ERRORMESSAGE := 'Cannot perform FINAL close with unreconciled intercompany balances';
                                            CALL <%AIM_DB%>.PUBLIC.THROW_UDP(50200, :ERRORMESSAGE, 1);
                                               END;
                                               END IF;
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
                                                               'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                                       IF (:CLOSETYPE = 'FINAL') THEN
                                            RAISE;
                                                       END IF;
                                END;
                        END;
                        END IF;
                        -- =====================================================================
                        -- Step 6: Lock the period
                        -- =====================================================================
                        CURRENTSTEP := 'Lock Period';
                        STEPSTARTTIME := SYSDATE();
                    BEGIN TRANSACTION;
                        BEGIN
                            NULL;
--                            -- Disable triggers during close (SQL Server specific)
--                            -- This pattern has no Snowflake equivalent
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. DISABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'DISABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                              ;
                        END;
                        BEGIN
                            UPDATE <%financial_planning%>.Planning.FiscalPeriod
                            SET
                                               IsClosed = 1,
                                               ClosedByUserID = :CLOSINGUSERID,
                                               ClosedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               FiscalPeriodID = :FISCALPERIODID;

                            -- Lock all budgets in this period
                            UPDATE <%financial_planning%>.Planning.BudgetHeader
                            SET
                                               StatusCode = 'LOCKED',
                                               LockedDateTime = SYSDATE(),
                                               ModifiedDateTime = SYSDATE()
                            WHERE
                                               --** SSC-FDM-TS0191 - TEXT COMPARISON ON A COLUMN DECLARED WITHOUT COLLATE IS CASE AND ACCENT SENSITIVE IN SNOWFLAKE; RESULTS DIFFER IF THE SOURCE DEFAULT COLLATION IS CASE OR ACCENT INSENSITIVE **
                                               StatusCode = 'APPROVED'
                              AND :FISCALPERIODID BETWEEN StartPeriodID AND EndPeriodID;

                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED', :SQLROWCOUNT);
                            COMMIT;
                        EXCEPTION
                            WHEN OTHER THEN
                                IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
                                               -- Manual resolution: Snowflake ROLLBACK takes no
                                               -- transaction name (one transaction per session).
                                               ROLLBACK;
                                END IF;
                            INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                            VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), (DATE_PART('EPOCH_MILLISECOND', SYSDATE()) - DATE_PART('EPOCH_MILLISECOND', :STEPSTARTTIME)), 'FAILED', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
                                RAISE;
                        END;
                        BEGIN
                            NULL;

--                            -- Re-enable triggers
--                            --** SSC-FDM-0052 - EXECUTE IMMEDIATE COMMENTED OUT BECAUSE ALL OF ITS DYNAMIC SQL BRANCHES WERE COMMENTED OUT; NO EXECUTABLE STATEMENT REMAINS. **
--                            --** SSC-FDM-TS0035 - TRIGGERS ARE NOT SUPPORTED IN SNOWFLAKE. ENABLE TRIGGER OPERATION IS OUT OF THE TRANSLATION SCOPE OF SNOWCONVERT AI. **
--                            EXECUTE IMMEDIATE 'ENABLE TRIGGER ALL ON Planning.BudgetLineItem'
                                                                                             ;
                        END;
                        -- =====================================================================
                        -- Step 7: Send notifications
                        -- =====================================================================
                        IF (:SENDNOTIFICATIONS = 1 AND :NOTIFICATIONRECIPIENTS IS NOT NULL) THEN
                        BEGIN
                                CURRENTSTEP := 'Send Notifications';
                                STEPSTARTTIME := SYSDATE();


                                EMAILSUBJECT := CONCAT('Financial Close Completed - ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')');
                                -- Build HTML email body
                                EMAILBODY := CONCAT('<html><body>', '<h2>Financial Close Summary</h2>', '<p><strong>Period:</strong> ', COALESCE(:PERIODNAME :: STRING, ''), ' (', COALESCE(:FISCALYEAR :: STRING, ''), ')</p>', '<p><strong>Close Type:</strong> ', COALESCE(:CLOSETYPE :: STRING, ''), '</p>', '<p><strong>Completed:</strong> ', COALESCE(TO_CHAR(SYSDATE(), 'YYYY-MM-DD HH24:MI:SS') :: STRING, ''), ' UTC</p>', '<h3>Processing Steps</h3>', '<table border="1" cellpadding="5">', '<tr><th>Step</th><th>Status</th><th>Duration (ms)</th><th>Rows</th></tr>');
                                /* Manual resolution: the source used the T-SQL
                                   aggregate-concatenation idiom
                                   SELECT @EmailBody = @EmailBody + ... FROM @StepResults,
                                   which appends one fragment per row. The generated
                                   RESULTSET/FOR loop assigned EMAILBODY from a value
                                   captured before the loop, so each row overwrote the
                                   previous one and only the last row survived. LISTAGG
                                   with an explicit ordering reproduces the accumulation. */
                                EMAILBODY := :EMAILBODY || (
                                               SELECT
                                                       LISTAGG(CONCAT('<tr><td>', COALESCE(StepName :: STRING, ''), '</td>', '<td style="color:', COALESCE(
                                                       CASE
                                            Status
                                            WHEN 'COMPLETED' THEN 'green' WHEN 'FAILED' THEN 'red' ELSE 'orange' END :: STRING, ''), '">', COALESCE(Status :: STRING, ''), '</td>', '<td>', COALESCE(DurationMs :: STRING, ''), '</td>', '<td>', COALESCE(NVL(CAST(RowsAffected AS VARCHAR), '-') :: STRING, ''), '</td></tr>'), '')
                                                       WITHIN GROUP (ORDER BY StepNumber)
                                               FROM
                                                       T_StepResults
                                );
                                EMAILBODY := :EMAILBODY || '</table></body></html>';
                                BEGIN
--                                               -- sp_send_dbmail - SQL Server Database Mail, no Snowflake equivalent
--                                               --** SSC-FDM-TS0049 - SP_SEND_DBMAIL TRANSLATED TO SNOWFLAKE NOTIFICATION. REQUIRES A NOTIFICATION INTEGRATION TO BE CONFIGURED. **
--                                               --** SSC-FDM-TS0050 - @BODY_FORMAT='HTML' TRANSLATED TO SNOWFLAKE.NOTIFICATION.TEXT_HTML. HTML RENDERING MAY DIFFER BETWEEN SQL SERVER DATABASE MAIL AND SNOWFLAKE EMAIL NOTIFICATIONS. **
--                                               --** SSC-FDM-TS0052 - SP_SEND_DBMAIL PARAMETERS NOT TRANSLATED: @profile_name. THESE PARAMETERS HAVE NO EQUIVALENT IN SNOWFLAKE SYSTEM$SEND_SNOWFLAKE_NOTIFICATION. **
--                                               EXEC msdb.dbo.sp_send_dbmail
--                                                   @profile_name = 'FinanceNotifications',
--                                                   @recipients = @NotificationRecipients,
--                                                   @subject = @EmailSubject,
--                                                   @body = @EmailBody,
--                                                   @body_format = 'HTML';
                                               CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(SNOWFLAKE.NOTIFICATION.TEXT_HTML(:EMAILBODY), SNOWFLAKE.NOTIFICATION.EMAIL_INTEGRATION_CONFIG('<your_email_notification_integration>', :EMAILSUBJECT, TRANSFORM(STRTOK_TO_ARRAY(:NOTIFICATIONRECIPIENTS, ';'), a -> TRIM(a))));

                                               INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status)
                                               VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'COMPLETED');
                                EXCEPTION
                                               WHEN OTHER THEN
                                                       -- Email failure shouldn't fail the close
                                                       INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
                                                       VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()), 'WARNING', :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/);
