                            OVERALLSTATUS := 'FAILED';
                            ERRORMESSAGE := :SQLERRM /*** SSC-FDM-TS0023 - ERROR MESSAGE COULD BE DIFFERENT IN SNOWFLAKE ***/;

                    -- Log final error
                    INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, Status, ErrorMessage)
                    VALUES ('ERROR_HANDLER', SYSDATE(), SYSDATE(), 'ERROR', :ERRORMESSAGE);
                    END;
                    CALL BuildResults();
                END;
            BuildResults PROCEDURE ()
            RETURNS VARCHAR
            AS
                BEGIN
                    -- =========================================================================
                    -- Build results XML
                    -- =========================================================================
                    CLOSERESULTS := (
                               SELECT
                            --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                            <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('RunID', :CLOSERUNID, 'PeriodID', :FISCALPERIODID, 'PeriodName', :PERIODNAME, 'FiscalYear', :FISCALYEAR, 'CloseType', :CLOSETYPE, 'Status', :OVERALLSTATUS, 'TotalDurationMs', DATEDIFF(MILLISECOND, :PROCSTARTTIME, SYSDATE()), 'ValidationErrors',
