322:                                                        INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, RowsAffected, ErrorMessage)
323:                                                        VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), (DATE_PART('EPOCH_MILLISECOND', SYSDATE()) - DATE_PART('EPOCH_MILLISECOND', :STEPSTARTTIME)),
324:                                                                CASE WHEN :RETURNCODE = 0 THEN 'COMPLETED' ELSE 'WARNING' END, :CONSOLIDATIONROWS, :CONSOLIDATIONERROR);
325:                                                        EXCEPTION
326:                                             WHEN OTHER THEN
327:                                                 INSERT INTO T_STEPRESULTS (StepName, StartTime, EndTime, DurationMs, Status, ErrorMessage)
328:                                                 VALUES (:CURRENTSTEP, :STEPSTARTTIME, SYSDATE(), DATEDIFF(MILLISECOND, :STEPSTARTTIME, SYSDATE()),
