                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Code', ErrorCode, 'Severity', Severity, 'text()', ErrorMessage), 'ValidationError')
                                FROM
                                               T_ValidationErrors
                            ), 'ProcessingSteps',
                            -- Processing steps
                            --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('Sequence', StepNumber, 'Name', StepName, 'Status', Status, 'DurationMs', DurationMs, 'RowsAffected', RowsAffected, 'ErrorMessage', ErrorMessage, 'OutputData', OutputData), 'Step')
                                FROM
                                               T_StepResults
                                ORDER BY StepNumber
                            ), 'Summary',
                            -- Summary metrics
                            -- Manual resolution: uncorrelated subquery over a temp table; valid in Snowflake.
                            (
                                SELECT
                                               --** SSC-FDM-TS0016 - XML COLUMNS IN SNOWFLAKE MIGHT HAVE A DIFFERENT FORMAT **
                                               <%AIM_DB%>.PUBLIC.FOR_XML_UDF(OBJECT_CONSTRUCT('CompletedSteps',
                                               --** SSC-FDM-0002 - CORRELATED SUBQUERIES MAY HAVE SOME FUNCTIONAL DIFFERENCES. **
                                               -- Manual resolution: uncorrelated subquery; valid in Snowflake.
                                               (SELECT
                                            COUNT(*) FROM
                                            T_StepResults
                                                       WHERE
